import React, { useState, useEffect, useRef } from 'react';

// プードル画像(放置日数で3段階)
const POODLE_IMAGES = {
  stage1: 'data:image/png;base64,',
  stage2: 'data:image/png;base64,',
  stage3: 'data:image/png;base64,',
};


const TASKS_KEY = 'houchi-daichou:tasks';
const HISTORY_KEY = 'houchi-daichou:history';

function loadFromStorage(key) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function HouchiDaichou() {
  const [tasks, setTasks] = useState(() => loadFromStorage(TASKS_KEY));
  const [history, setHistory] = useState(() => loadFromStorage(HISTORY_KEY));
  const [showAddModal, setShowAddModal] = useState(false);
  const [taskInput, setTaskInput] = useState('');
  const [activeTask, setActiveTask] = useState(null);
  const [showTrashModal, setShowTrashModal] = useState(false);
  const [toast, setToast] = useState('');
  const [dragIndex, setDragIndex] = useState(null);

  useEffect(() => {
    try {
      localStorage.setItem(TASKS_KEY, JSON.stringify(tasks));
    } catch {}
  }, [tasks]);

  useEffect(() => {
    try {
      localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
    } catch {}
  }, [history]);

  const showToast = (msg) => {
    setToast(msg);
    setTimeout(() => setToast(''), 1800);
  };

  const daysSince = (dateStr) => {
    const created = new Date(dateStr);
    const now = new Date();
    return Math.max(0, Math.floor((now - created) / (1000 * 60 * 60 * 24)));
  };

  // 5日ごとにレベルが上がり、サイズと色の濃さが段階的に変化する。
  // レベル0-2:クリーム(stage1) / 3-5:黄色(stage2) / 6以降:紫(stage3)
  // レベル8(40日)で成長は打ち止め。
  const MAX_POODLE_LEVEL = 8;

  const poodleVisual = (days) => {
    const level = Math.min(Math.floor(days / 5), MAX_POODLE_LEVEL);
    const stage = level < 3 ? 1 : level < 6 ? 2 : 3;
    const posInStage = level % 3; // 0,1,2: 同じ画像の中での進み具合
    const sizeRatio = 1 + (level / MAX_POODLE_LEVEL) * 0.45; // 徐々に大きく
    const saturate = 1 + posInStage * 0.18; // 徐々に色が濃く
    const brightness = 1 - posInStage * 0.04; // 徐々にやや暗く
    return { stage, sizeRatio, filter: `saturate(${saturate}) brightness(${brightness})` };
  };

  const addTask = () => {
    const name = taskInput.trim();
    if (!name) return;
    const newTask = {
      id: 'task_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
      name,
      createdAt: new Date().toISOString(),
    };
    setTasks([newTask, ...tasks]);
    setTaskInput('');
    setShowAddModal(false);
    showToast('とりあえず入れておこう。');
  };

  const openDetail = (task) => {
    setActiveTask(task);
  };

  const moveToHistory = (status) => {
    if (!activeTask) return;
    setTasks(tasks.filter(t => t.id !== activeTask.id));
    setHistory([{ ...activeTask, status, movedAt: new Date().toISOString() }, ...history]);
    setActiveTask(null);
    showToast(status === 'done' ? 'おつかれさま！ひとつ減ったよ。' : 'ひとつ減ると、ちょっと嬉しい。');
  };

  const restoreFromHistory = (id) => {
    const h = history.find(x => x.id === id);
    if (!h) return;
    setHistory(history.filter(x => x.id !== id));
    const { status, movedAt, ...taskData } = h;
    setTasks([taskData, ...tasks]);
    showToast('リストに戻したよ。');
  };

  // ≡ハンドルだけをドラッグ起点にするPointer Events実装。
  // ネイティブHTML5 D&D(draggable属性)はiOSのタッチでは並べ替えが成立せず、
  // カード全体のタッチジェスチャーを奪ってスクロールも止めてしまうため使わない。
  // setPointerCaptureは小さい要素だとiOSで安定して効かないことがあるため、
  // ドラッグ中はwindow全体でpointermove/upを監視する方式にしている。
  const dragIndexRef = useRef(null);
  useEffect(() => {
    dragIndexRef.current = dragIndex;
  }, [dragIndex]);

  useEffect(() => {
    const handleMove = (e) => {
      const current = dragIndexRef.current;
      if (current === null) return;
      const target = document.elementFromPoint(e.clientX, e.clientY);
      const card = target && target.closest('[data-task-index]');
      if (!card) return;
      const overIndex = Number(card.dataset.taskIndex);
      if (overIndex === current) return;
      setTasks((prev) => {
        const newTasks = [...prev];
        const [moved] = newTasks.splice(current, 1);
        newTasks.splice(overIndex, 0, moved);
        return newTasks;
      });
      setDragIndex(overIndex);
    };
    const handleEnd = () => {
      if (dragIndexRef.current !== null) setDragIndex(null);
    };
    window.addEventListener('pointermove', handleMove);
    window.addEventListener('pointerup', handleEnd);
    window.addEventListener('pointercancel', handleEnd);
    return () => {
      window.removeEventListener('pointermove', handleMove);
      window.removeEventListener('pointerup', handleEnd);
      window.removeEventListener('pointercancel', handleEnd);
    };
  }, []);

  const handlePointerDown = (e, index) => {
    e.preventDefault();
    setDragIndex(index);
  };

  const catImg = (visual, baseSize) => (
    <img
      src={POODLE_IMAGES['stage' + visual.stage]}
      alt="プードル"
      style={{ width: Math.round(baseSize * visual.sizeRatio), height: 'auto', display: 'block', filter: visual.filter }}
    />
  );

  const msgs = { 1: 'まだ大丈夫。', 2: 'そろそろ？', 3: '……いいかげんにして。' };

  return (
    <div style={{
      fontFamily: '"Hiragino Maru Gothic ProN","Hiragino Sans","Yu Gothic",sans-serif',
      background: 'radial-gradient(circle at 20% 0%, #FFF0E6 0%, #FFF8F0 45%)',
      minHeight: '100vh',
      display: 'flex',
      justifyContent: 'center',
      color: '#4A3F3F',
    }}>
      <div style={{ width: '100%', maxWidth: 480, minHeight: '100vh', background: '#FFF8F0', display: 'flex', flexDirection: 'column' }}>

        {/* header */}
        <div style={{ padding: 'calc(26px + env(safe-area-inset-top)) 20px 14px', textAlign: 'center', position: 'relative' }}>
          <button
            onClick={() => setShowTrashModal(true)}
            style={{
              position: 'absolute', top: 'calc(22px + env(safe-area-inset-top))', right: 20,
              background: '#fff', border: '1px solid #F0E4DC', borderRadius: 100,
              width: 40, height: 40, fontSize: 17, cursor: 'pointer', color: '#A89A94',
            }}
          >🗑</button>
          <h1 style={{ fontSize: 25, margin: 0, fontWeight: 800, letterSpacing: '0.04em' }}>
            放置台帳 <span style={{ fontSize: 19 }}>🌱</span>
          </h1>
          <p style={{ margin: '6px 0 0', fontSize: 12, color: '#A89A94' }}>
            やることも、やらないことも、自分のペースで。
          </p>
        </div>

        {/* add button */}
        <button
          onClick={() => setShowAddModal(true)}
          style={{
            margin: '2px 20px 16px', padding: 15,
            background: 'linear-gradient(135deg,#FF8FA3,#FF6B8B)',
            color: '#fff', border: 'none', borderRadius: 18, fontSize: 15, fontWeight: 700,
            boxShadow: '0 8px 18px -6px rgba(255,107,139,0.55)', cursor: 'pointer',
          }}
        >＋ やることを追加</button>

        <p style={{
          margin: '0 20px 14px', padding: '10px 14px', background: '#FFF2F5', borderRadius: 12,
          fontSize: 11.5, color: '#C77B8E', textAlign: 'center', lineHeight: 1.6,
        }}>
          タップして「やった」「やらない」／≡を押さえて上下にドラッグで並べ替え
        </p>

        {/* list */}
        <div style={{ flex: 1, padding: '0 20px 50px', display: 'flex', flexDirection: 'column', gap: 12 }}>
          {tasks.length === 0 ? (
            <div style={{ textAlign: 'center', color: '#A89A94', marginTop: 60, fontSize: 14, lineHeight: 1.9 }}>
              <span style={{ fontSize: 56, display: 'block', marginBottom: 10 }}>🐾</span>
              まだ何も放置してないよ。<br />気になってることがあれば、追加してみてね。
            </div>
          ) : (
            tasks.map((t, i) => {
              const days = daysSince(t.createdAt);
              const visual = poodleVisual(days);
              const dayColor = visual.stage === 1 ? '#D8A468' : visual.stage === 2 ? '#C98A0E' : '#B0479E';
              return (
                <div
                  key={t.id}
                  data-task-index={i}
                  style={{
                    background: '#fff', borderRadius: 20, padding: '14px 12px 14px 16px',
                    display: 'flex', alignItems: 'center', gap: 12,
                    boxShadow: '0 3px 10px -4px rgba(150,120,110,0.18)', border: '1px solid #F0E4DC',
                    opacity: dragIndex === i ? 0.6 : 1,
                  }}
                >
                  <div
                    onClick={() => openDetail(t)}
                    style={{ cursor: 'pointer', display: 'flex', alignItems: 'center' }}
                  >
                    {catImg(visual, 42)}
                  </div>
                  <div
                    onClick={() => openDetail(t)}
                    style={{ flex: 1, minWidth: 0, cursor: 'pointer' }}
                  >
                    <div style={{
                      fontSize: 15, fontWeight: 700, whiteSpace: 'nowrap',
                      overflow: 'hidden', textOverflow: 'ellipsis',
                    }}>{t.name}</div>
                    <div style={{ fontSize: 13, fontWeight: 800, marginTop: 3, color: dayColor }}>
                      {days}日
                    </div>
                  </div>
                  <div
                    onPointerDown={(e) => handlePointerDown(e, i)}
                    onContextMenu={(e) => e.preventDefault()}
                    style={{
                      color: '#C9BAB2', fontSize: 20, padding: '10px 8px', cursor: 'grab', touchAction: 'none',
                      userSelect: 'none', WebkitUserSelect: 'none', WebkitTouchCallout: 'none',
                    }}
                  >
                    <span
                      style={{
                        userSelect: 'none', WebkitUserSelect: 'none', WebkitTouchCallout: 'none',
                        pointerEvents: 'none',
                      }}
                    >≡</span>
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* add modal */}
        {showAddModal && (
          <div
            onClick={(e) => { if (e.target === e.currentTarget) setShowAddModal(false); }}
            style={{
              position: 'fixed', inset: 0, background: 'rgba(70,55,50,0.35)',
              display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 50,
            }}
          >
            <div style={{
              background: '#FFF8F0', width: '100%', maxWidth: 480, borderRadius: '24px 24px 0 0', padding: '22px 20px 30px',
            }}>
              <p style={{ fontSize: 17, fontWeight: 800, margin: '0 0 16px', textAlign: 'center' }}>やることを追加</p>
              <input
                type="text"
                value={taskInput}
                onChange={(e) => setTaskInput(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') addTask(); }}
                placeholder="例：保険の見直し"
                maxLength={30}
                style={{
                  width: '100%', padding: '14px 16px', borderRadius: 14, border: '1.5px solid #F0E4DC',
                  background: '#fff', fontSize: 15, outline: 'none', marginBottom: 14, boxSizing: 'border-box',
                }}
                autoFocus
              />
              <button
                onClick={addTask}
                style={{
                  width: '100%', padding: 15, background: 'linear-gradient(135deg,#FF8FA3,#FF6B8B)',
                  color: '#fff', border: 'none', borderRadius: 14, fontSize: 15, fontWeight: 700, cursor: 'pointer',
                }}
              >追加する</button>
              <button
                onClick={() => setShowAddModal(false)}
                style={{
                  width: '100%', padding: 12, background: 'none', border: 'none', color: '#A89A94',
                  fontSize: 13.5, marginTop: 8, cursor: 'pointer',
                }}
              >キャンセル</button>
            </div>
          </div>
        )}

        {/* detail modal */}
        {activeTask && (
          <div
            onClick={(e) => { if (e.target === e.currentTarget) setActiveTask(null); }}
            style={{
              position: 'fixed', inset: 0, background: 'rgba(70,55,50,0.35)',
              display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 50,
            }}
          >
            <div style={{
              background: '#FFF8F0', width: '100%', maxWidth: 480, borderRadius: '24px 24px 0 0', padding: '22px 20px 30px',
            }}>
              {(() => {
                const days = daysSince(activeTask.createdAt);
                const visual = poodleVisual(days);
                return (
                  <>
                    <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 6 }}>
                      {catImg(visual, 110)}
                    </div>
                    <p style={{ textAlign: 'center', fontSize: 18, fontWeight: 800, margin: '8px 0 2px' }}>{activeTask.name}</p>
                    <p style={{ textAlign: 'center', fontSize: 13, color: '#A89A94', margin: '0 0 4px' }}>放置 {days}日</p>
                    <p style={{ textAlign: 'center', fontSize: 13, color: '#A89A94', margin: '0 0 18px' }}>{msgs[visual.stage]}</p>
                  </>
                );
              })()}
              <button
                onClick={() => moveToHistory('done')}
                style={{
                  width: '100%', padding: 15, border: 'none', borderRadius: 14, fontSize: 15, fontWeight: 700,
                  marginBottom: 10, cursor: 'pointer', background: '#5FCB8E', color: '#fff',
                }}
              >✓ やった！</button>
              <button
                onClick={() => moveToHistory('trashed')}
                style={{
                  width: '100%', padding: 15, border: 'none', borderRadius: 14, fontSize: 15, fontWeight: 700,
                  marginBottom: 10, cursor: 'pointer', background: '#FF6B6B', color: '#fff',
                }}
              >🗑 もうやらない</button>
              <button
                onClick={() => setActiveTask(null)}
                style={{
                  width: '100%', padding: 12, background: 'none', border: 'none', color: '#A89A94',
                  fontSize: 13.5, cursor: 'pointer',
                }}
              >閉じる</button>
            </div>
          </div>
        )}

        {/* trash/history modal */}
        {showTrashModal && (
          <div
            onClick={(e) => { if (e.target === e.currentTarget) setShowTrashModal(false); }}
            style={{
              position: 'fixed', inset: 0, background: 'rgba(70,55,50,0.35)',
              display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 50,
            }}
          >
            <div style={{
              background: '#FFF8F0', width: '100%', maxWidth: 480, borderRadius: '24px 24px 0 0', padding: '22px 20px 30px',
              maxHeight: '80vh', display: 'flex', flexDirection: 'column',
            }}>
              <p style={{ fontSize: 17, fontWeight: 800, margin: '0 0 16px', textAlign: 'center' }}>ゴミ箱・履歴</p>
              <div style={{ overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 6 }}>
                {history.length === 0 ? (
                  <div style={{ textAlign: 'center', color: '#A89A94', fontSize: 13, padding: '30px 0', lineHeight: 1.8 }}>
                    まだ何もないよ。<br />「やった」「もうやらない」にしたものがここに残るよ。
                  </div>
                ) : (
                  history.map(h => (
                    <div key={h.id} style={{
                      background: '#fff', border: '1px solid #F0E4DC', borderRadius: 16,
                      padding: '12px 14px', display: 'flex', alignItems: 'center', gap: 12,
                    }}>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{
                          fontSize: 14, fontWeight: 700, whiteSpace: 'nowrap',
                          overflow: 'hidden', textOverflow: 'ellipsis',
                        }}>{h.name}</div>
                        <div style={{
                          fontSize: 11.5, marginTop: 2, fontWeight: 700,
                          color: h.status === 'done' ? '#5FCB8E' : '#FF6B6B',
                        }}>{h.status === 'done' ? '✓ やった' : '🗑 もうやらない'}</div>
                      </div>
                      <button
                        onClick={() => restoreFromHistory(h.id)}
                        style={{
                          background: '#FF8FA3', color: '#fff', border: 'none', borderRadius: 100,
                          padding: '8px 14px', fontSize: 12, fontWeight: 800, cursor: 'pointer',
                        }}
                      >戻す</button>
                    </div>
                  ))
                )}
              </div>
              <button
                onClick={() => setShowTrashModal(false)}
                style={{
                  width: '100%', padding: 12, background: 'none', border: 'none', color: '#A89A94',
                  fontSize: 13.5, marginTop: 8, cursor: 'pointer',
                }}
              >閉じる</button>
            </div>
          </div>
        )}

        {/* toast */}
        {toast && (
          <div style={{
            position: 'fixed', bottom: 30, left: '50%', transform: 'translateX(-50%)',
            background: '#4A3F3F', color: '#fff', padding: '12px 22px', borderRadius: 100,
            fontSize: 13.5, zIndex: 100, whiteSpace: 'nowrap',
          }}>{toast}</div>
        )}
      </div>
    </div>
  );
}

export default HouchiDaichou;
